<template>
  <q-dialog v-model="dialogOpen" no-backdrop-dismiss>
    <q-card class="variables-popover">
      <!-- Header -->
      <q-card-section class="row items-center q-pb-none">
        <template v-if="showCreateForm || editingVariable">
          <q-btn flat round dense icon="arrow_back" size="sm" @click="cancelForm" />
          <div class="text-subtitle1 text-weight-bold q-ml-xs">
            {{ editingVariable ? $t('edit_variable') : $t('new_variable') }}
          </div>
        </template>
        <template v-else>
          <div class="text-subtitle1 text-weight-bold">{{ $t('variables') }}</div>
        </template>
        <q-space />
        <q-btn flat round dense icon="close" size="sm" v-close-popup />
      </q-card-section>

      <!-- Main view: list + search -->
      <template v-if="!showCreateForm && !editingVariable">
        <q-card-section class="q-pt-sm q-pb-none">
          <q-input
            v-model="searchText"
            dense
            rounded
            outlined
            :placeholder="$t('search_variables')"
          >
            <template v-slot:prepend>
              <q-icon name="search" size="xs" />
            </template>
            <template v-slot:append>
              <q-icon
                v-if="searchText"
                name="close"
                size="xs"
                class="cursor-pointer"
                @click="searchText = ''"
              />
            </template>
          </q-input>
        </q-card-section>

        <q-card-section class="variables-list q-pt-sm">
          <div
            v-if="!variables || variables.length === 0"
            class="text-grey text-center q-pa-lg"
          >
            {{ $t('no_workflow_variables') }}
          </div>

          <div v-for="group in filteredGroups" :key="group.type" class="q-mb-sm">
            <div class="text-caption text-grey-7 text-weight-medium q-mb-xs q-px-sm">
              {{ group.label }}
            </div>

            <q-list dense>
              <q-item
                v-for="variable in group.variables"
                :key="variable.id"
                class="variable-row rounded-borders"
              >
                <q-item-section avatar class="variable-icon-section">
                  <div class="type-icon-circle" :class="'type-icon-circle--' + group.type">
                    <q-icon :name="group.icon" size="16px" color="white" />
                  </div>
                </q-item-section>

                <q-item-section>
                  <q-item-label class="text-body2 text-weight-medium">{{ variable.name }}</q-item-label>
                </q-item-section>

                <q-item-section side class="variable-value-section">
                  <span class="text-caption text-grey-6">
                    {{ getDisplayValue(variable) }}
                  </span>
                </q-item-section>

                <q-item-section side class="variable-actions">
                  <div class="row no-wrap">
                    <q-btn flat round dense icon="edit" size="xs" @click="startEdit(variable)">
                      <q-tooltip>{{ $t('edit_variable') }}</q-tooltip>
                    </q-btn>
                    <q-btn flat round dense icon="delete_outline" size="xs" color="negative" @click="confirmDelete(variable)">
                      <q-tooltip>{{ $t('delete_variable') }}</q-tooltip>
                    </q-btn>
                  </div>
                </q-item-section>
              </q-item>
            </q-list>
          </div>
        </q-card-section>

        <q-card-section class="q-pt-none">
          <q-btn
            unelevated
            rounded
            color="positive"
            :label="$t('new_variable')"
            icon="add"
            class="full-width new-variable-btn"
            no-caps
            @click="showCreateForm = true"
          />
        </q-card-section>
      </template>

      <!-- Create / Edit form -->
      <template v-if="showCreateForm || editingVariable">
        <q-card-section class="q-pt-md">
          <!-- Type selector (only for create) -->
          <div v-if="!editingVariable" class="type-selector q-mb-lg">
            <div
              v-for="t in typeOptions"
              :key="t.value"
              class="type-option"
              :class="{ 'type-option--selected': formType === t.value }"
              @click="formType = t.value"
            >
              <div class="type-icon-circle" :class="'type-icon-circle--' + t.value">
                <q-icon :name="t.icon" size="28px" color="white" />
              </div>
              <span class="type-option-label">{{ t.label }}</span>
            </div>
          </div>

          <!-- Name -->
          <div class="field-group q-mb-md">
            <label class="field-label">{{ $t('variable_name_label') }}</label>
            <q-input
              v-model="formName"
              outlined
              rounded
              dense
              placeholder="..."
              :error="!!nameError"
              :error-message="nameError ? $t(nameError) : ''"
              @update:model-value="nameError = null"
            />
          </div>

          <!-- Value -->
          <div v-if="formType !== 'document'" class="field-group q-mb-lg">
            <label class="field-label">{{ $t('variable_default_value') }}</label>
            <q-toggle
              v-if="formType === 'boolean'"
              v-model="formBoolValue"
              :label="formBoolValue ? 'Yes' : 'No'"
              color="positive"
            />
            <q-input
              v-else
              v-model="formValue"
              outlined
              rounded
              dense
              :placeholder="formType === 'number' ? '0' : $t('default_value')"
              :type="formType === 'number' ? 'number' : 'text'"
            />
          </div>
          <div v-else class="field-group q-mb-lg">
            <label class="field-label">{{ $t('variable_default_value') }}</label>
            <div class="text-caption text-grey-6">
              {{ $t('document_variable_auto_set') }}
            </div>
          </div>

          <!-- Save button -->
          <q-btn
            unelevated
            rounded
            no-caps
            color="primary"
            icon="check"
            :label="$t('create_variable')"
            class="full-width save-btn"
            @click="submitForm"
          />
        </q-card-section>
      </template>
    </q-card>
  </q-dialog>
</template>

<script lang="ts">
import { defineComponent, ref, computed } from 'vue';
import { useQuasar } from 'quasar';
import type { WorkflowVariable } from '../workflow-advanced-models';
import {
  groupWorkflowVariables,
  filterWorkflowVariables,
  createVariable,
  validateVariableName,
  getVariableDisplayValue,
  getTypeConfig,
} from './workflowVariableUtils';
import type { VarType } from './workflowVariableUtils';

export default defineComponent({
  name: 'AdvancedWorkflowVariables',
  props: {
    modelValue: {
      type: Boolean,
      default: false,
    },
    variables: {
      type: Array as () => WorkflowVariable[],
      default: () => [],
    },
  },
  emits: ['update:modelValue', 'create', 'update', 'delete'],
  setup(props, { emit }) {
    const $q = useQuasar();
    const searchText = ref('');
    const showCreateForm = ref(false);
    const editingVariable = ref<WorkflowVariable | null>(null);

    const formName = ref('');
    const formType = ref<VarType>('text');
    const formValue = ref('');
    const formBoolValue = ref(false);
    const nameError = ref<string | null>(null);

    const dialogOpen = computed({
      get: () => props.modelValue,
      set: (val: boolean) => emit('update:modelValue', val),
    });

    const grouped = computed(() => groupWorkflowVariables(props.variables));
    const filteredGroups = computed(() =>
      filterWorkflowVariables(grouped.value, searchText.value),
    );

    const typeOptions = [
      { value: 'text' as VarType, ...getTypeConfig('text') },
      { value: 'number' as VarType, ...getTypeConfig('number') },
      { value: 'boolean' as VarType, ...getTypeConfig('boolean') },
      { value: 'document' as VarType, ...getTypeConfig('document') },
    ];

    function getDisplayValue(v: WorkflowVariable): string {
      return getVariableDisplayValue(v);
    }

    function startEdit(variable: WorkflowVariable) {
      editingVariable.value = variable;
      formName.value = variable.name;
      formType.value = variable.var_type;
      if (variable.var_type === 'boolean') {
        formBoolValue.value = !!(variable.value ?? variable.default_value);
      } else {
        formValue.value = String(variable.value ?? variable.default_value ?? '');
      }
      nameError.value = null;
    }

    function cancelForm() {
      showCreateForm.value = false;
      editingVariable.value = null;
      formName.value = '';
      formValue.value = '';
      formBoolValue.value = false;
      formType.value = 'text';
      nameError.value = null;
    }

    function submitForm() {
      const excludeId = editingVariable.value?.id;
      const error = validateVariableName(formName.value, props.variables, excludeId);
      if (error) {
        nameError.value = error;
        return;
      }

      const type = editingVariable.value ? editingVariable.value.var_type : formType.value;
      let value: string | number | boolean | null;
      if (type === 'boolean') {
        value = formBoolValue.value;
      } else if (type === 'number') {
        const num = parseFloat(formValue.value);
        value = isNaN(num) ? 0 : num;
      } else if (type === 'document') {
        // Document variables don't have a manual default value
        value = null;
      } else {
        value = formValue.value;
      }

      if (editingVariable.value) {
        emit('update', {
          ...editingVariable.value,
          name: formName.value.trim(),
          default_value: value,
          value: value,
        });
      } else {
        const variable = createVariable(formName.value, type, value);
        emit('create', variable);
      }

      cancelForm();
    }

    function confirmDelete(variable: WorkflowVariable) {
      $q.dialog({
        title: '',
        message: $q.lang.label.remove || 'Delete this variable?',
        cancel: true,
        persistent: false,
      }).onOk(() => {
        emit('delete', variable.id);
      });
    }

    return {
      dialogOpen,
      searchText,
      showCreateForm,
      editingVariable,
      formName,
      formType,
      formValue,
      formBoolValue,
      nameError,
      filteredGroups,
      typeOptions,
      getDisplayValue,
      startEdit,
      cancelForm,
      submitForm,
      confirmDelete,
    };
  },
});
</script>

